// ---- internal helpers --------------------------------------------------------------------------------------------
const put = (g, x, y, z, pair) => g.set(x, y, z, ...pair);
const leaves = (name) => [name, { persistent: "true" }];
const within = (x, y, z, boxes = []) => boxes.some(([x0, y0, z0, x1, y1, z1]) =>
  x >= Math.min(x0, x1) && x <= Math.max(x0, x1) && y >= Math.min(y0, y1) && y <= Math.max(y0, y1) &&
